 "guidance": [
  {
   "metric": "volume",
   "statement": "Expect 20% to 25% volume growth quarter-on-quarter in mobile business as consumer demand strengthens and order book is strong.",
   "quote": "we expect 20% to 25% volume growth quarter-on-quarter growth as consumer demand strengthens and we have a strong order book.",
   "page": 4,
   "horizon": "next quarter",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Absolute profit growth and operating margin restoration expected from next fiscal FY28.",
   "quote": "positions the company to drive absolute profit growth and restore operating margins from the next fiscal of '27, '28.",
   "page": 3,
   "horizon": "FY28",
   "quantitative": false
  },
  {
   "metric": "revenue",
   "statement": "Telecom revenues expected to be between INR6,700 crores to INR7,000 crores in this fiscal.",
   "quote": "we're going to be somewhere between INR6,700 crores to INR7,000 crores in this fiscal.",
   "page": 20,
   "horizon": "FY27",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "Camera module capacity in Q Tech to expand from 70 million to 180 million to 190 million annually over 15 to 18 months.",
   "quote": "We are expanding the capacities of camera module in subsidiary Q Tech, which is an ECMS beneficiary for smartphones from 70 million annually to 180 million to 190 million annually over the next 15 to 18 months",
   "page": 5,
   "horizon": "15 to 18 months",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Export additions of 15 million to 20 million units adding INR18,000 crores to INR20,000 crores in a couple of years.",
   "quote": "we feel that in a couple of years, that can add almost 15 million to 20 million to our numbers, additional quantity in a couple of years. So which is an addition of almost INR18,000 crores to INR20,000 crores of revenue.",
   "page": 10,
   "horizon": "couple of years",
   "quantitative": true
  }
 ],
